javascript:(function(){if(window.__hwp){alert('Watch Party already running');return;}window.__hwp=true;const p=new URLSearchParams(location.search);const S=p.get('hwpServer')||prompt('Server URL (wss://...):','wss://hotstar-watch-party.onrender.com');const R=p.get('hwpRoom')||prompt('Room ID:');if(!S||!R){window.__hwp=false;return;}const D=3;let ws,video,role,sync=false;const b=document.createElement('div');b.style.cssText='position:fixed;bottom:16px;right:16px;z-index:999999;padding:7px 16px;border-radius:20px;font:bold 13px/1 sans-serif;color:#fff;box-shadow:0 2px 8px rgba(0,0,0,.5);background:#888;';b.textContent='● Connecting…';document.body.appendChild(b);function sb(t,c){b.textContent='● '+t;b.style.background=c;}ws=new WebSocket(S);const id='bm-'+Math.random().toString(36).slice(2,7);ws.onopen=()=>ws.send(JSON.stringify({type:'join',roomId:R,clientId:id}));ws.onclose=()=>sb('Disconnected','#c00');ws.onerror=()=>sb('Error','#c00');ws.onmessage=({data})=>{let m;try{m=JSON.parse(data);}catch{return;}if(m.type==='joined'){role=m.role;sb(role==='host'?'Host':'Guest — Synced',role==='host'?'#1a7':'#17a');wfv(v=>{video=v;if(role==='host')al();});return;}if(!video)return;if(m.type==='sync-request'&&role==='host'){snd({type:'sync-response',time:video.currentTime,paused:video.paused});return;}if(m.type==='sync-response'&&role==='guest'){as(m.time,m.paused);return;}if(role==='guest'){if(m.type==='play')as(m.time,false);if(m.type==='pause')as(m.time,true);if(m.type==='seek')as(m.time,video.paused);}};function al(){video.addEventListener('play',()=>{if(!sync)snd({type:'play',time:video.currentTime});});video.addEventListener('pause',()=>{if(!sync)snd({type:'pause',time:video.currentTime});});video.addEventListener('seeked',()=>{if(!sync)snd({type:'seek',time:video.currentTime});});}function as(t,pa){sync=true;if(Math.abs(video.currentTime-t)>D)video.currentTime=t;if(pa&&!video.paused)video.pause();else if(!pa&&video.paused)video.play().catch(()=>{});setTimeout(()=>{sync=false;},300);}function snd(m){if(ws.readyState===1)ws.send(JSON.stringify(m));}function wfv(cb){const t=setInterval(()=>{const v=document.querySelector('video');if(v){clearInterval(t);cb(v);}},500);}})();
